/* Aubry & Vent — Caliber 08
   Dark, ruled, instrument-like. Serif for language, mono for anything the
   workshop would have measured. */

:root {
  --ink: #0c0d0e;
  --ink-2: #131516;
  --ink-3: #191c1d;
  --line: rgba(214, 205, 188, 0.14);
  --line-strong: rgba(214, 205, 188, 0.28);
  --text: #e6e1d7;
  --text-2: #a5a094;
  --text-3: #78746b;
  --brass: #c2a06b;
  --brass-dim: #8d7548;
  --steel: #7f9099;

  --serif: 'Spectral', Georgia, 'Times New Roman', serif;
  --sans: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --mono: 'IBM Plex Mono', ui-monospace, 'SFMono-Regular', Menlo, monospace;

  --page: min(1180px, 100% - 3rem);
  --ease: cubic-bezier(0.22, 0.68, 0.31, 1);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 5.5rem;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--ink);
  color: var(--text);
  font-family: var(--sans);
  font-weight: 300;
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  margin: 0;
  font-family: var(--serif);
  font-weight: 300;
  letter-spacing: -0.012em;
}

p,
dl,
dd,
ul,
ol {
  margin: 0;
}

ul,
ol {
  padding: 0;
  list-style: none;
}

a {
  color: inherit;
}

::selection {
  background: var(--brass);
  color: var(--ink);
}

:focus-visible {
  outline: 1px solid var(--brass);
  outline-offset: 3px;
}

.skip {
  position: absolute;
  left: -9999px;
  top: 0;
  z-index: 50;
  background: var(--brass);
  color: var(--ink);
  padding: 0.6rem 1rem;
  font-size: 0.8rem;
}

.skip:focus {
  left: 1rem;
  top: 1rem;
}

/* A faint vertical grid behind the whole page — the layout lines of a
   technical drawing, not decoration you are meant to notice. */
.page {
  position: relative;
  overflow-x: hidden;
}

.page::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background: radial-gradient(
    120% 80% at 50% -20%,
    rgba(194, 160, 107, 0.09),
    transparent 60%
  );
}

/* ---------- top bar ---------- */

.topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 2rem;
  width: 100%;
  padding: 0.9rem max(1.5rem, calc((100% - var(--page)) / 2));
  background: rgba(12, 13, 14, 0.82);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--line);
}

.topbar__mark {
  display: flex;
  align-items: baseline;
  gap: 0.7rem;
  text-decoration: none;
  margin-right: auto;
}

.topbar__maker {
  font-family: var(--serif);
  font-size: 1rem;
  letter-spacing: 0.02em;
}

.topbar__ref {
  font-family: var(--mono);
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--brass);
}

.topbar__nav {
  display: flex;
  gap: 1.6rem;
}

.topbar__nav a {
  font-size: 0.78rem;
  letter-spacing: 0.05em;
  color: var(--text-2);
  text-decoration: none;
  padding-bottom: 2px;
  border-bottom: 1px solid transparent;
  transition: color 0.25s var(--ease), border-color 0.25s var(--ease);
}

.topbar__nav a:hover {
  color: var(--text);
  border-bottom-color: var(--brass);
}

.topbar__cta {
  font-family: var(--mono);
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--brass);
  border: 1px solid var(--line-strong);
  padding: 0.5rem 0.95rem;
  transition: background 0.25s var(--ease), color 0.25s var(--ease);
}

.topbar__cta:hover {
  background: var(--brass);
  color: var(--ink);
}

/* ---------- hero ---------- */

main {
  position: relative;
  z-index: 1;
}

.hero {
  width: var(--page);
  margin: 0 auto;
  padding: clamp(4.5rem, 12vw, 9rem) 0 clamp(3rem, 7vw, 5rem);
}

.hero__eyebrow {
  display: flex;
  align-items: center;
  gap: 1rem;
  font-family: var(--mono);
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--text-3);
}

.hero__rule {
  flex: 0 0 3rem;
  height: 1px;
  background: var(--line-strong);
}

.hero__title {
  margin-top: 1.6rem;
  font-size: clamp(3.4rem, 12vw, 8.5rem);
  line-height: 0.9;
  letter-spacing: -0.03em;
}

.hero__num {
  font-style: italic;
  color: var(--brass);
}

.hero__sub {
  max-width: 34ch;
  margin-top: 1.8rem;
  font-family: var(--serif);
  font-size: clamp(1.15rem, 2.2vw, 1.5rem);
  line-height: 1.45;
  color: var(--text);
}

.hero__body {
  max-width: 48ch;
  margin-top: 1.2rem;
  color: var(--text-2);
  font-size: 1rem;
}

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem;
  margin-top: 2.4rem;
}

.btn {
  display: inline-block;
  font-family: var(--mono);
  font-size: 0.72rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  text-decoration: none;
  padding: 0.85rem 1.5rem;
  border: 1px solid var(--line-strong);
  background: transparent;
  color: var(--text);
  cursor: pointer;
  transition: background 0.25s var(--ease), color 0.25s var(--ease),
    border-color 0.25s var(--ease);
}

.btn--solid {
  background: var(--brass);
  border-color: var(--brass);
  color: var(--ink);
}

.btn--solid:hover {
  background: #d8b981;
  border-color: #d8b981;
}

.btn--ghost:hover {
  border-color: var(--brass);
  color: var(--brass);
}

.hero__figures {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  margin-top: clamp(3rem, 8vw, 5.5rem);
  border-top: 1px solid var(--line-strong);
}

.hero__figures > div {
  padding: 1.4rem 1.2rem 0 0;
  border-right: 1px solid var(--line);
}

.hero__figures > div:last-child {
  border-right: 0;
}

.hero__figures dt {
  font-family: var(--serif);
  font-size: clamp(1.6rem, 3.4vw, 2.4rem);
  line-height: 1;
  color: var(--text);
}

.hero__figures dd {
  margin-top: 0.55rem;
  font-family: var(--mono);
  font-size: 0.66rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-3);
}

/* ---------- sections ---------- */

.section,
.reserve {
  width: var(--page);
  margin: 0 auto;
  padding: clamp(3.5rem, 9vw, 7rem) 0;
  border-top: 1px solid var(--line);
}

.section {
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 0.9s var(--ease), transform 0.9s var(--ease);
}

.hero {
  opacity: 0;
  transform: translateY(12px);
  transition: opacity 1s var(--ease), transform 1s var(--ease);
}

.section[data-shown='true'],
.hero[data-shown='true'] {
  opacity: 1;
  transform: none;
}

.section__head {
  display: grid;
  grid-template-columns: 4rem minmax(0, 1fr) minmax(0, 1fr);
  gap: 2.5rem;
  align-items: start;
  margin-bottom: clamp(2.5rem, 5vw, 4rem);
}

.section__index {
  font-family: var(--mono);
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  color: var(--brass-dim);
  padding-top: 0.6rem;
}

.section__label {
  font-family: var(--mono);
  font-size: 0.66rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--text-3);
  margin-bottom: 0.7rem;
}

.section__title {
  font-size: clamp(1.9rem, 4vw, 3rem);
  line-height: 1.05;
}

.section__lede {
  color: var(--text-2);
  font-size: 0.95rem;
  max-width: 42ch;
  padding-top: 0.4rem;
}

/* ---------- 01 power path ---------- */

.path {
  position: relative;
  border-top: 1px solid var(--line);
}

.stage {
  position: relative;
  display: grid;
  grid-template-columns: 4rem minmax(0, 1fr) minmax(0, 15rem);
  gap: 2.5rem;
  align-items: baseline;
  padding: 1.9rem 1rem 1.9rem 0;
  border-bottom: 1px solid var(--line);
  transition: background 0.35s var(--ease);
}

/* the rail the energy runs down */
.stage::before {
  content: '';
  position: absolute;
  left: calc(4rem - 1px - 1.25rem);
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--line-strong);
}

.stage:first-child::before {
  top: 50%;
}

.stage:last-child::before {
  bottom: 50%;
}

.stage::after {
  content: '';
  position: absolute;
  left: calc(4rem - 1.25rem - 3.5px);
  top: calc(1.9rem + 0.35em);
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ink);
  border: 1px solid var(--brass-dim);
  transition: background 0.35s var(--ease), box-shadow 0.35s var(--ease);
}

.stage:hover {
  background: linear-gradient(90deg, rgba(194, 160, 107, 0.05), transparent 70%);
}

.stage:hover::after {
  background: var(--brass);
  box-shadow: 0 0 0 4px rgba(194, 160, 107, 0.14);
}

.stage__index {
  font-family: var(--mono);
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  color: var(--text-3);
}

.stage__name {
  font-size: clamp(1.25rem, 2.4vw, 1.7rem);
  line-height: 1.15;
}

.stage__detail {
  margin-top: 0.6rem;
  color: var(--text-2);
  font-size: 0.95rem;
  max-width: 52ch;
}

.stage__figure {
  font-family: var(--mono);
  font-size: 0.78rem;
  line-height: 1.5;
  color: var(--brass);
  text-align: right;
}

/* ---------- 02 layers ---------- */

.layers {
  display: grid;
  gap: 1px;
  background: var(--line);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.layer {
  background: var(--ink);
  padding: 1.8rem 1.6rem 1.8rem 0;
  display: grid;
  grid-template-columns: minmax(0, 20rem) minmax(0, 1fr);
  gap: 2.5rem;
  align-items: center;
  transition: background 0.35s var(--ease);
}

.layer:hover {
  background: var(--ink-2);
}

.layer__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1.5rem;
}

.layer__name {
  font-size: 1.2rem;
}

.layer__thickness {
  font-family: var(--mono);
  font-size: 0.85rem;
  color: var(--brass);
}

.layer__bar {
  grid-column: 1;
  height: 6px;
  background: rgba(214, 205, 188, 0.07);
  margin-top: -1rem;
}

.layer__bar span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--brass-dim), var(--brass));
  transition: width 0.8s var(--ease);
}

.layer__note {
  grid-column: 2;
  grid-row: 1 / span 2;
  color: var(--text-2);
  font-size: 0.95rem;
  max-width: 54ch;
}

/* ---------- 03 specification ---------- */

.spec {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: 4rem;
  border-top: 1px solid var(--line);
}

.spec__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1.5rem;
  padding: 0.95rem 0;
  border-bottom: 1px solid var(--line);
}

.spec__row dt {
  font-size: 0.9rem;
  color: var(--text-2);
  white-space: nowrap;
}

.spec__row dd {
  font-family: var(--mono);
  font-size: 0.85rem;
  color: var(--text);
  text-align: right;
}

/* ---------- 04 workshop ---------- */

.atelier {
  display: grid;
  gap: 0;
  border-top: 1px solid var(--line);
}

.atelier li {
  display: grid;
  grid-template-columns: 4rem minmax(0, 1fr);
  gap: 2.5rem;
  padding: 1.6rem 0;
  border-bottom: 1px solid var(--line);
}

.atelier__index {
  font-family: var(--mono);
  font-size: 0.72rem;
  color: var(--text-3);
  padding-top: 0.35rem;
}

.atelier p {
  font-family: var(--serif);
  font-size: clamp(1.05rem, 2vw, 1.3rem);
  line-height: 1.55;
  color: var(--text);
  max-width: 62ch;
}

/* ---------- 05 finishes ---------- */

.finishes {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.25rem;
}

.finish {
  display: flex;
  flex-direction: column;
  gap: 1.4rem;
  padding: 2rem 1.6rem;
  background: var(--ink-2);
  border: 1px solid var(--line);
  transition: border-color 0.3s var(--ease), background 0.3s var(--ease),
    transform 0.4s var(--ease);
}

.finish:hover {
  background: var(--ink-3);
  border-color: var(--line-strong);
  transform: translateY(-3px);
}

.finish.is-chosen {
  border-color: var(--brass);
  background: var(--ink-3);
}

.finish__name {
  font-size: 1.45rem;
  line-height: 1.15;
}

.finish__desc {
  margin-top: 0.7rem;
  color: var(--text-2);
  font-size: 0.92rem;
}

.finish__price {
  font-family: var(--serif);
  font-size: 2rem;
  line-height: 1;
  padding-top: 1.2rem;
  border-top: 1px solid var(--line);
}

.finish__currency {
  font-family: var(--mono);
  font-size: 0.68rem;
  letter-spacing: 0.16em;
  color: var(--text-3);
  vertical-align: 0.5em;
  margin-right: 0.25rem;
}

.finish__meta {
  display: grid;
  gap: 0.9rem;
  margin-top: auto;
}

.finish__meta dt {
  font-family: var(--mono);
  font-size: 0.62rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-3);
}

.finish__meta dd {
  margin-top: 0.2rem;
  font-size: 0.9rem;
  color: var(--text);
}

.finish__choose {
  font-family: var(--mono);
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding: 0.8rem 1rem;
  background: transparent;
  border: 1px solid var(--line-strong);
  color: var(--text);
  cursor: pointer;
  transition: background 0.25s var(--ease), color 0.25s var(--ease),
    border-color 0.25s var(--ease);
}

.finish__choose:hover {
  border-color: var(--brass);
  color: var(--brass);
}

.finish.is-chosen .finish__choose {
  background: var(--brass);
  border-color: var(--brass);
  color: var(--ink);
}

/* ---------- 06 reservation ---------- */

.reserve {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: clamp(2.5rem, 6vw, 5rem);
  align-items: start;
}

.reserve__intro .section__index {
  padding-top: 0;
  margin-bottom: 0.9rem;
}

.reserve__note {
  margin-top: 1.6rem;
  color: var(--text-2);
  font-size: 0.95rem;
  max-width: 40ch;
  padding-left: 1.1rem;
  border-left: 1px solid var(--brass-dim);
}

.form {
  display: grid;
  gap: 1.6rem;
  padding: 2rem;
  background: var(--ink-2);
  border: 1px solid var(--line);
}

.field {
  display: grid;
  gap: 0.55rem;
}

.field label {
  font-family: var(--mono);
  font-size: 0.66rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-3);
}

.field input,
.field select {
  width: 100%;
  font-family: var(--sans);
  font-size: 1rem;
  color: var(--text);
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--line-strong);
  padding: 0.6rem 0;
  border-radius: 0;
  transition: border-color 0.25s var(--ease);
}

.field select {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--text-2) 50%),
    linear-gradient(135deg, var(--text-2) 50%, transparent 50%);
  background-position: right 6px center, right 1px center;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

.field select option {
  background: var(--ink-2);
  color: var(--text);
}

.field input:focus,
.field select:focus {
  outline: none;
  border-bottom-color: var(--brass);
}

.form__foot {
  display: grid;
  gap: 1rem;
  padding-top: 0.4rem;
}

.form__foot .btn {
  justify-self: start;
}

.form__summary {
  font-family: var(--mono);
  font-size: 0.75rem;
  line-height: 1.6;
  color: var(--brass);
}

.confirm {
  padding: 2.4rem 2rem;
  background: var(--ink-2);
  border: 1px solid var(--brass-dim);
}

.confirm__mark {
  font-family: var(--mono);
  font-size: 0.68rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--brass);
}

.confirm__text {
  margin-top: 1.2rem;
  font-family: var(--serif);
  font-size: clamp(1.15rem, 2.2vw, 1.45rem);
  line-height: 1.5;
}

.confirm__fine {
  margin-top: 1.4rem;
  padding-top: 1.4rem;
  border-top: 1px solid var(--line);
  font-size: 0.85rem;
  color: var(--text-3);
}

/* ---------- footer ---------- */

.footer {
  position: relative;
  z-index: 1;
  width: var(--page);
  margin: 0 auto;
  padding: 2.5rem 0 3.5rem;
  border-top: 1px solid var(--line);
  display: flex;
  flex-wrap: wrap;
  gap: 1.2rem 2.5rem;
  align-items: baseline;
  font-size: 0.8rem;
  color: var(--text-3);
}

.footer__mark {
  margin-right: auto;
  font-family: var(--mono);
  font-size: 0.7rem;
  letter-spacing: 0.1em;
}

.footer__mail a {
  color: var(--text-2);
  text-decoration: none;
  border-bottom: 1px solid var(--line-strong);
}

.footer__mail a:hover {
  color: var(--brass);
  border-bottom-color: var(--brass);
}

.footer__links {
  display: flex;
  gap: 1.5rem;
}

/* ---------- narrower ---------- */

@media (max-width: 900px) {
  .section__head {
    grid-template-columns: 3rem minmax(0, 1fr);
    gap: 1.5rem;
  }

  .section__lede {
    grid-column: 2;
  }

  .stage,
  .atelier li {
    grid-template-columns: 3rem minmax(0, 1fr);
    gap: 1.5rem;
  }

  .stage::before {
    left: calc(3rem - 1px - 0.75rem);
  }

  .stage::after {
    left: calc(3rem - 0.75rem - 3.5px);
  }

  .stage__figure {
    grid-column: 2;
    text-align: left;
    margin-top: 0.9rem;
  }

  .layer {
    grid-template-columns: minmax(0, 1fr);
    gap: 1rem;
  }

  .layer__note,
  .layer__bar {
    grid-column: 1;
    grid-row: auto;
  }

  .layer__bar {
    margin-top: 0;
  }

  .spec {
    grid-template-columns: minmax(0, 1fr);
  }

  .finishes {
    grid-template-columns: minmax(0, 1fr);
  }

  .reserve {
    grid-template-columns: minmax(0, 1fr);
  }

  .topbar__nav {
    display: none;
  }
}

@media (max-width: 560px) {
  :root {
    --page: calc(100% - 2rem);
  }

  .hero__figures {
    grid-template-columns: repeat(2, 1fr);
  }

  .hero__figures > div {
    border-bottom: 1px solid var(--line);
    padding-bottom: 1.2rem;
  }

  .hero__figures > div:nth-child(2n) {
    border-right: 0;
  }

  .form,
  .confirm {
    padding: 1.5rem 1.2rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

